 "questions": [{"id": "aq-aiml-tel-l2-m2-p1", "order": 1, "title": "Practice Draft: L2 Model Evidence Validation Checklist", "description": "Has you checked remaining missing values, timestamp continuity, field meaning, label availability, and baseline feature suitability before applying anomaly logic?", "instructions": "Draft a first pass using the relevant template fields. Think through the evidence manually first and use AI only as a coach for guided questions, clarity checks, missed-risk prompts, or limitation checks.", "submission_required": false, "expected_submission_type": "text"}], "templates": [], "submissions": [], "total_score": 0, "max_attempts": null, "artifact_type": "practice", "passing_score": null, "allow_resubmission": true, "require_review_unlock": false}}, "knowledge": {"technical_concepts_learnt": "Completeness review, field suitability, missing-data pattern check, label availability review, baseline readiness decision", "academic_refresher_concepts": "Spreadsheet scan, feature meaning, missing value basics, labelled versus unlabelled data"}, "module_no": 2, "description": "Build the L2 Model Evidence Validation Checklist by completing the L2 telemetry baseline workflow task: The learner receives the cleaned telemetry sample with 690 usable rows, selected fields sensor_temp, voltage, current, and rpm, 4 remaining missing sensor_temp values, 3 remaining missing rpm values, and no labelled anomaly column. The learner must decide whether this cleaned sample is fit for beginner-level baseline testing and document what limitations remain before applying any anomaly logic.", "estimatedTime": "2 hrs", "pressure_points": "Learner may apply anomaly logic before checking remaining missing values, field meaning, label absence, and baseline feature suitability.", "learning_content": {"major_concepts": "Field completeness, missing-data pattern, feature suitability, label availability, baseline model-readiness decision", "reason_behind_concept": "Baseline results are only interpretable when the learner knows what evidence remains incomplete and what the workflow cannot prove.", "implementation_context_when_to_use": "Use before applying threshold or statistical logic to confirm that the cleaned sample is usable only for controlled baseline testing."}, "student_confusion": "How do I know whether a cleaned sample is good enough for beginner baseline testing?", "artifact_submitted": false, "completion_percentage": 0, "engineering_workflow_stage": "Model Evidence Validation", "module_specific_problem_statement": "You receive the cleaned telemetry sample with 690 usable rows, selected fields sensor_temp, voltage, current, and rpm, 4 remaining missing sensor_temp values, 3 remaining missing rpm values, and no labelled anomaly column. You must decide whether this cleaned sample is fit for beginner-level baseline testing and document what limitations remain before applying any anomaly logic."}, {"id": "mod-aiml-tel-l2-m3", "title": "Guided Work Action or Handoff", "tools": {"tools_used": "Spreadsheet/notebook, missing-data handling note, baseline method table, suspicious-output review sheet", "tool_type_free_or_paid": "free"}, "stages": [{"key": "engage", "status": "not_started", "time_spent_seconds": 0}, {"key": "explore", "status": "not_started", "time_spent_seconds": 0}, {"key": "explain", "status": "not_started", "time_spent_seconds": 0}, {"key": "express", "status": "not_started", "time_spent_seconds": 0}, {"key": "empower", "status": "not_started", "time_spent_seconds": 0}, {"key": "evolve", "status": "not_started", "time_spent_seconds": 0}], "status": "available", "content": [{"id": "c-aiml-tel-l2-m3-empower", "url": "https://content.rareminds.dev/courses/aiml-tel-l2/content/c-aiml-tel-l2-m3-empower", "order": 5, "stage": "empower", "title": "Decision check: can another engineer reproduce and review the baseline workflow?", "status": "published", "isViewed": false, "facilitator": [{"question": "AI coach for L2 Baseline Anomaly Workflow Note: What workflow decision can you defend: further testing, evidence fixes, escalation, or blocked for model use?", "follow_up": "Decide whether the workflow result supports learning, more testing, evidence fixing, escalation, or blocked model use."}], "content_type": "decision check", "duration_seconds": 900}, {"id": "c-aiml-tel-l2-m3-engage", "url": "https://content.rareminds.dev/courses/aiml-tel-l2/content/c-aiml-tel-l2-m3-engage", "order": 1, "stage": "engage", "title": "Workflow action kickoff: build a reproducible baseline without overclaiming accuracy", "status": "published", "isViewed": false, "facilitator": [{"question": "AI coach for L2 Baseline Anomaly Workflow Note: What is the risk of running simple anomaly logic without documenting field choice and missing-data handling?", "follow_up": "Name the risk of running logic without documenting method choice, missing-data handling, or limitation."}], "content_type": "case brief", "duration_seconds": 900}, {"id": "c-aiml-tel-l2-m3-evolve", "url": "https://content.rareminds.dev/courses/aiml-tel-l2/content/c-aiml-tel-l2-m3-evolve", "order": 6, "stage": "evolve", "title": "Reflection: transfer simple anomaly workflow logic to another unlabelled case", "status": "published", "isViewed": false, "facilitator": [{"question": "AI coach for L2 Baseline Anomaly Workflow Note: How would this workflow logic transfer to another unlabelled anomaly-detection case?", "follow_up": "State how this simple baseline rule could be reviewed before L3 integration-readiness."}], "content_type": "reflection prompt", "duration_seconds": 900}, {"id": "c-aiml-tel-l2-m3-explain", "url": "https://content.rareminds.dev/courses/aiml-tel-l2/content/c-aiml-tel-l2-m3-explain", "order": 3, "stage": "explain", "title": "Guide: simple threshold or statistical anomaly logic for baseline review", "status": "published", "isViewed": false, "facilitator": [{"question": "AI coach for L2 Baseline Anomaly Workflow Note: What concept helps 