view_unlock": true}, "express": {"id": "ma-aiml-tel-l5-m0-p", "questions": [{"id": "aq-aiml-tel-l5-m0-p1", "order": 1, "title": "Practice Draft: L5 Solution Readiness Sheet", "description": "Can you explain how data readiness, baseline workflow, integration, reporting, and governance connect in the full solution?", "instructions": "Draft a first pass using the relevant template fields. Think through the evidence manually first and use AI only as a coach for guided questions, clarity checks, missed-risk prompts, or limitation checks.", "submission_required": false, "expected_submission_type": "text"}], "templates": [], "submissions": [], "total_score": 0, "max_attempts": null, "artifact_type": "practice", "passing_score": null, "allow_resubmission": true, "require_review_unlock": false}}, "knowledge": {"technical_concepts_learnt": "Solution-readiness boundary, workflow chain, human review, governance awareness", "academic_refresher_concepts": "System thinking, decision support, governance controls"}, "module_no": 0, "description": "Build the L5 Solution Readiness Sheet by completing the L5 telemetry AI/ML task: The learner is moving from module-level work to end-to-end solution validation. The risk is that separate artifacts may look individually acceptable but fail as a connected decision-support workflow. The learner must understand how data readiness, baseline modelling, integration, reporting, and governance connect before making a final recommendation.", "estimatedTime": "2 hrs", "pressure_points": "Learner may judge artifacts individually without checking whether the full workflow is safe as connected decision support.", "learning_content": {"major_concepts": "End-to-end workflow map, L1-L4 evidence summary, decision-support boundary, human review requirement, governance awareness", "reason_behind_concept": "A solution can be safe only when data, model, integration, reporting, and risk evidence work together under human control.", "implementation_context_when_to_use": "Use before final solution validation so the learner understands how earlier evidence connects and where governance applies."}, "student_confusion": "If each earlier level has artifacts, does that mean the full AI/ML workflow is ready?", "artifact_submitted": false, "completion_percentage": 0, "engineering_workflow_stage": "Solution Readiness Orientation", "module_specific_problem_statement": "You are moving from module-level work to end-to-end solution validation. The risk is that separate artifacts may look individually acceptable but fail as a connected decision-support workflow. You must understand how data readiness, baseline modelling, integration, reporting, and governance connect before making a final recommendation."}, {"id": "mod-aiml-tel-l5-m1", "title": "Case Intake & Role Boundary", "tools": {"tools_used": "End-to-end case intake template, stakeholder request, risk register", "tool_type_free_or_paid": "free"}, "stages": [{"key": "engage", "status": "not_started", "time_spent_seconds": 0}, {"key": "explore", "status": "not_started", "time_spent_seconds": 0}, {"key": "explain", "status": "not_started", "time_spent_seconds": 0}, {"key": "express", "status": "not_started", "time_spent_seconds": 0}, {"key": "empower", "status": "not_started", "time_spent_seconds": 0}, {"key": "evolve", "status": "not_started", "time_spent_seconds": 0}], "status": "available", "content": [{"id": "c-aiml-tel-l5-m1-empower", "url": "https://content.rareminds.dev/courses/aiml-tel-l5/content/c-aiml-tel-l5-m1-empower", "order": 5, "stage": "empower", "title": "Decision check: defend the end-to-end case intake note decision with evidence", "status": "published", "isViewed": false, "facilitator": [{"question": "AI coach for L5 End-to-End Case Intake Note: What decision can you defend using evidence from this module?", "follow_up": "Make the decision yourself using evidence; state whether the workflow is ready as a supervised decision-support prototype, ready only for further controlled testing, or blocked until stronger evidence and governance controls are added."}], "content_type": "checklist", "duration_seconds": 1200}, {"id": "c-aiml-tel-l5-m1-engage", "url": "https://content.rareminds.dev/courses/aiml-tel-l5/content/c-aiml-tel-l5-m1-engage", "order": 1, "stage": "engage", "title": "End-to-End Case Intake Note kickoff: workplace risk and decision boundary", "status": "published", "isViewed": false, "facilitator": [{"question": "AI coach for L5 End-to-End Case Intake Note: What is the workplace risk in this module before any solution or recommendation is suggested?", "follow_up": "Name the risk using this module context: Learner may answer readiness without clarifying users, autonomy boundary, unresolved risks, or recommendation format."}], "content_type": "case brief", "duration_seconds": 900}, {"id": "c-aiml-tel-l5-m1-evolve", "url": "https://content.rareminds.dev/courses/aiml-tel-l5/content/c-aiml-tel-l5-m1-evolve", "order": 6, "stage": "evolve", "title": "Reflection: transfer end-to-end case intake note reasoning to the next AI/ML workflow", "status": "published", "isViewed": false, "facilitator": [{"question": "AI coach for L5 End-to-End Case Intake Note: How can this learning transfer to the next dataset, team handoff, or level?", "follow_up": "State one reusable rule for transferring this artifact to workplace decision-support governance."}], "content_type": "reflection prompt", "duration_seconds": 1200}, {"id": "c-aiml-tel-l5-m1-explain", "url": "https://content.rareminds.dev/courses/aiml-tel-l5/content/c-aiml-tel-l5-m1-explain", "order": 3, "stage": "explain", "title": "Guide: concepts and role boundary for end-to-end case intake note", "status": "published", "isViewed": false, "facilitator": [{"question": "AI coach for L5 End-to-End Case Intake Note: Which concept or boundary helps you understand this issue?", "follow_up": "Explain in simple words using these concepts: Stakeholder request, decision-support objective, expected users, autonomy boundary, unresolved risks, role boundary"}], "content_type": "explainer", "duration_seconds": 900}, {"id": "c-aiml-tel-l5-m1-explore", "url": "https://content.rareminds.dev/courses/aiml-tel-l5/content/c-aiml-tel-l5-m1-explore", "order": 2, "stage": "explore", "title": "Inspect evidence for end-to-end case intake note", "status": "published", "isViewed": false, "facilitator": [{"question": "AI coach for L5 End-to-End Case Intake Note: What visible evidence should you inspect before completing this artifact?", "follow_up": "Point to module-specific evidence: stakeholder request, expected users, decision-support objective, autonomy boundary, available L1-L4 evidence, unresolved risks, final recommendation needs"}], "content_type": "practice activity", "duration_seconds": 900}, {"id": "c-aiml-tel-l5-m1-express", "url": "https://content.rareminds.dev/courses/aiml-tel-l5/content/c-aiml-tel-l5-m1-express", "order": 4, "stage": "express", "title": "Template task: complete the L5 End-to-End Case Intake Note", "status": "published", "isViewed": false, "facilitator": [{"question": "AI coach for L5 End-to-End Case Intake Note: What exactly will you write in the artifact so it is useful to a reviewer?", "follow_up": "Include the required fields: Stakeholder request, decision-support objective, available evidence, expected users, autonomy boundary, unresolved risks, role boundary, clarification questions, intake decision"}], "content_type": "worksheet", "duration_seconds": 1200}], "support": {"ai_support_tips": "Ask AI to help list intake questions about users, autonomy, evidence, and governance; make the final boundary decision yourself.", "module_continuity_link": "Uses Module 0 solution context and produces intake for full evidence validation."}, "artifacts": {"empower": {"id": "ma-aiml-tel-l5-m1-f", "questions": [{"id": "aq-aiml-tel-l5-m1-f1", "order": 1, "title": "L5 End-to-End Case Intake Note", "description": "Has you clarified decision-support meaning,