estions": [{"id": "aq-aiml-tel-l5-m6-p1", "order": 1, "title": "Practice Draft: L5 Certification Portfolio Pack", "description": "Can a reviewer trace certification-level capability across L1-L5 evidence, unresolved risks, governance controls, and transfer-to-work proof?", "instructions": "Draft a first pass using the relevant template fields. Think through the evidence manually first and use AI only as a coach for guided questions, clarity checks, missed-risk prompts, or limitation checks.", "submission_required": false, "expected_submission_type": "text"}], "templates": [], "submissions": [], "total_score": 0, "max_attempts": null, "artifact_type": "practice", "passing_score": null, "allow_resubmission": true, "require_review_unlock": false}}, "knowledge": {"technical_concepts_learnt": "Portfolio synthesis, evidence mapping, unresolved risk summary, certification proof, transfer note", "academic_refresher_concepts": "Portfolio structure, reflective validation, capability proof"}, "module_no": 6, "description": "Build the L5 Certification Portfolio Pack by completing the L5 telemetry AI/ML task: The reviewer needs certification-level proof that the learner can handle an end-to-end AI/ML telemetry workflow responsibly. The learner must compile all L1–L5 evidence into a final portfolio showing capability maturity from data readiness to decision-support validation.", "estimatedTime": "4 hrs", "pressure_points": "Learner may submit final reports without proving maturity across data readiness, baseline workflow, integration, reporting, governance, and closure.", "learning_content": {"major_concepts": "Certification portfolio, L1-L5 artifact chain, capability evidence map, unresolved risk summary, transfer-to-work note", "reason_behind_concept": "Certification proof requires a connected evidence trail showing decisions, limitations, governance, and transfer readiness.", "implementation_context_when_to_use": "Use at the end of L5 to assemble certification-level proof across all progression levels."}, "student_confusion": "How do I prove end-to-end AI/ML capability responsibly at certification level?", "artifact_submitted": false, "completion_percentage": 0, "engineering_workflow_stage": "Certification Portfolio Validation", "module_specific_problem_statement": "The reviewer needs certification-level proof that you can handle an end-to-end AI/ML telemetry workflow responsibly. You must compile all L1–L5 evidence into a final portfolio showing capability maturity from data readiness to decision-support validation."}], "duration": "22 hours", "course_id": "crs-aiml-tel-l5", "xp_reward": 1300, "started_at": null, "why_needed": "AI/ML engineers must validate whether connected workflow evidence is strong enough for supervised decision-support without allowing autonomous or unsupported engineering decisions.", "course_code": "AIML-TEL-L5", "description": "You can evaluate an end-to-end AI/ML telemetry decision-support workflow across data readiness, baseline modelling, integration handoff, reporting, governance, risk, and final stakeholder decision-readiness.", "domain_name": "Data & AI", "level_label": "L5", "sequence_no": 5, "completed_at": null, "how_to_build": "AI/ML engineers must review the full L1-L4 evidence chain, validate unresolved risks, define safe-use conditions, require human review, and communicate a final governed recommendation.", "current_level": 1, "priority_band": "A", "thumbnail_url": "https://images.unsplash.com/photo-1515879218367-8466d910aaa4?q=80&w=2670&auto=format&fit=crop", "required_level": 3, "capability_name": "AI/ML End-to-End Solution Validation and Governance", "difficulty_level": "advanced", "job_pathway_role": "AI / ML Engineer", "problem_artifacts": [{"id": "pa-aiml-tel-l5-m0", "no": 1, "text": "", "score": 0, "title": "L5 Solution Readiness Sheet", "module": "Industry, Role & Course Readiness", "prompt": "Final artifact question: Can the learner explain how data readiness, baseline workflow, integration, reporting, and governance connect in the full solution? Input: use the L5 course case, prior module artifacts where applicable, and this evidence: L1-L4 evidence chain, 720-row original pack, 690-row cleaned sample, 26 anomaly flags, integration schema, revised LLM report, risk register, governance boundary. Action: complete the L5 Solution Readiness Sheet by filling these required fields: L5 purpose, full workflow map, L1-L4 evidence summary, decision-support boundary, human review requirement, governance awareness, readiness decision. Evidence to cite: L1-L4 evidence chain, 720-row original pack, 690-row cleaned sample, 26 anomaly flags, integration schema, revised LLM report, risk register, governance boundary. Output decision: state whether the workflow is ready as a supervised decision-support prototype, ready only for further controlled testing, or blocked until stronger evidence and governance controls are added. Do not approve autonomous engineering decisions, production deployment, failure diagnosis, or unsupervised use without labelled evidence, complete metadata, and governance controls. Do not ask AI to produce the final answer; use AI only as a coach for guided questions and clarity checks.", "status": "not_started"}, {"id": "pa-aiml-tel-l5-m1", "no": 2, "text": "", "score": 0, "title": "L5 End-to-End Case Intake Note", "module": "Case Intake & Role Boundary", "prompt": "Final artifact question: Has the learner clarified decision-support meaning, users, autonomy boundary, available evidence, unresolved risks, and recommendation format? Input: use the L5 course case, prior module artifacts where applicable, and this evidence: stakeholder request, expected users, decision-support objective, autonomy boundary, available L1-L4 evidence, unresolved risks, final recommendation needs. Action: complete the L5 End-to-End Case Intake Note by filling these required fields: Stakeholder request, decision-support objective, available evidence, expected users, autonomy boundary, unresolved risks, role boundary, clarification questions, intake decision. Evidence to cite: stakeholder request, expected users, decision-support objective, autonomy boundary, available L1-L4 evidence, unresolved risks, final recommendation needs. Output decision: state whether the workflow is ready as a supervised decision-support prototype, ready only for further controlled testing, or blocked until stronger evidence and governance controls are added. Do not approve autonomous engineering decisions, production deployment, failure diagnosis, or unsupervised use without labelled evidence, complete metadata, and governance controls. Do not ask AI to produce the final answer; use AI only as a coach for guided questions and clarity checks.", "status": "not_started"}, {"id": "pa-aiml-tel-l5-m2", "no": 3, "text": "", "score": 0, "title": "L5 Solution Evidence Validation Checklist", "module": "Evidence / Requirement Validation", "prompt": "Final artifact question: Has the learner checked consistency across L1 readiness, L2 baseline workflow, L3 integration schema, L4 report wording, and risk-register status? Input: use the L5 course case, prior module artifacts where applicable, and this evidence: original data issues, cleaned sample decisions, baseline anomaly logic, integration schema, report wording, 11-risk register, unresolved field metadata and labelled-data gaps. Action: complete the L5 Solution Evidence Validation Checklist by filling these required fields: Evidence item, source/owner, L1 readiness consistency, L2 model consistency, L3 integration consistency, L4 report consistency, risk-register status, solution-readiness decision. Evidence to cite: original data issues, cleaned sample decisions, baseline anomaly logic, integration schema, report wording, 11-risk register, unresolved field metadata and labelled-data gaps. Output decision: state whether the workflow is ready as a supervised decision-support prototype, ready only for further controlled testing, or blocked until stronger evidence and governance controls are added. Do not approve autonomous engineering decisions, production deployment, failure diagnosis, or unsupervised use without labelled evidence, complete metadata, and governance controls. Do not ask AI to produce the final answer; use AI only as a coach for guided questions and clarity checks.", "status": "not_started"}, {"id": "pa-aiml-tel-l5-m3", "no": 4, "text": "", "score": 0, "title": "L5 Decision-Support Validation Note", "module": "Guided Work Action or Handoff", "prompt": "Final artifact question: Does the learner define safe-use conditions, human review requirements, prohibited uses, and a final evidence-based recommendation? Input: use the L5 course case, prior module artifacts where applicable, and this evidence: evidence chain summary, safe-use conditions, human review requirements, prohibited uses, unresolved risks, stakeholder handoff needs. Action: complete the L5 Decision-Support Validation Note by filling these required fields: Evidence chain summary, safe-use conditions, human review requirement, prohibited uses, final recommendation, stakeholder handoff, final action decision. Evidence to cite: evidence chain summary, safe-use conditions, human review requirements, prohibited uses, unresolved risks, stakeholder handoff needs. Output decision: state whether the workflow is ready as a supervised decision-support prototype, ready only for further controlled testing, or blocked until stronger evidence and governance controls are added. Do not approve autonomous engineering decisions, production deployment, failure diagnosis, or unsupervised use without labelled evidence, complete metadata, and governance controls. Do not ask AI to produce the final answer; use AI only as a coach for guided questions and clarity checks.", "status": "not_started"}, {"id": "pa-aiml-tel-l5-m4", "no": 5, "text": "", "score": 0, "title": "L5 Governance Risk and Escalation Note", "module": "Exceptions, Blockers, Risks & Escalations", "prompt": "Final artifact question: Has the learner classified incomplete field metadata and no labelled failure dataset as prototype conditions, deployment blockers, or further-testing needs? Input: use the L5 course case, prior module artifacts where applicable, and this evidence: incomplete field metadata, no labelled failure dataset, two unresolved risks, consequence, severity, owner, control requirement, escalation reason. Action: complete the L5 Governance Risk and Escalation Note by filling these required fields: Risk ID, governance category, unresolved evidence, consequence, severity, owner, escalation reason, control required, recommended next action. Evidence to cite: incomplete field metadata, no labelled failure dataset, two unresolved risks, consequence, severity, owner, control requirement, escalation reason. Output decision: state whether the workflow is ready as a supervised decision-support prototype, ready only for further controlled testing, or blocked until stronger evidence and governance controls are added. Do not approve autonomous engineering decisions, production deployment, failure diagnosis, or unsupervised use without labelled evidence, complete metadata, and governance controls. Do not ask AI to produce the final answer; use AI only as a coach for guided questions and clarity checks.", "status": "not_started"}, {"id": "pa-aiml-tel-l5-m5", "no": 6, "text": "", "score": 0, "title": "L5 Final Solution Quality and Closure Report", "module": "Quality, Communication & Closure", "prompt": "Final artifact question: Is the final recommendation clear about supervised prototype use, controlled testing, blocked status, governance controls, human review, and next action? Input: use the L5 course case, prior module artifacts where applicable, and this evidence: work completed, evidence used, final readiness recommendation, limitations, governance controls, human-review requirement, stakeholder message, closure decision. Action: complete the L5 Final Solution Quality and Closure Report by filling these required fields: Work completed, evidence used, final readiness recommendation, limitations, governance controls, human-review requirement, stakeholder message, closure confidence, closure decision. Evidence to cite: work completed, evidence used, final readiness recommendation, limitations, governance controls, human-review requirement, stakeholder message, closure decision. Output decision: state whether the workflow is ready as a supervised decision-support prototype, ready only for further controlled testing, or blocked until stronger evidence and governance controls are added. Do not approve autonomous engineering decisions, production deployment, failure diagnosis, or unsupervised use without labelled evidence, complete metadata, and governance controls. Do not ask AI to produce the final answer; use AI only as a coach for guided questions and clarity checks.", "status": "not_started"}, {"id": "pa-aiml-tel-l5-m6", "no": 7, "text": "", "score": 0, "title": "L5 Certification Portfolio Pack", "module": "Portfolio, Transfer & Final Validation", "prompt": "Final artifact question: Can a reviewer trace certification-level capability across L1-L5 evidence, unresolved risks, governance controls, and transfer-to-work proof? Input: use the L5 course case, prior module artifacts where applicable, and this evidence: full L1-L5 artifact chain, capability evidence map, unresolved risk summary, retry log, certification proof, transfer-to-work note. Action: complete the L5 Certification Portfolio Pack by filling these required fields: Portfolio cover note, L1-L5 artifact chain, capability evidence map, unresolved risk summary, retry log, certification proof, transfer-to-work note, reviewer validation. Evidence to cite: full L1-L5 artifact chain, capability evidence map, unresolved risk summary, retry log, certification proof, transfer-to-work note. Output decision: state whether the workflow is ready as a supervised decision-support prototype, ready only for further controlled testing, or blocked until stronger evidence and governance controls are added. Do not approve autonomous engineering decisions, production deployment, failure diagnosis, or unsupervised use without labelled evidence, complete metadata, and governance controls. Do not ask AI to produce the final answer; use AI only as a coach for guided questions and clarity checks.", "status": "not_started"}], "problem_statement": {"title": "End-to-End AI/ML Telemetry Decision-Support Validation", "description": "The team now wants to decide whether the AI/ML telemetry workflow is mature enough to become a controlled decision-support prototype. You receive the full evidence chain from L1 to L4: the 720-row original telemetry pack, the 690-row cleaned sample, selected telemetry fields, 26 anomaly flags, integration output schema, latency expectation of 500 milliseconds, a revised LLM report, a risk register with 11 open or mitigated risks, and a stakeholder request for a final readiness recommendation. However, no labelled failure dataset exists, some field metadata is still incomplete, two risks remain unresolved, and the report must not be used as an autonomous engineering decision. You must decide whether the AI/ML workflow is ready as a supervised decision-support prototype, ready only for further controlled testing, or blocked until stronger evidence and governance controls are added."}, "certification_value": "Certification-level L5 evidence for end-to-end telemetry AI/ML decision-support validation and governance readiness", "completion_percentage": 0, "common_course_problem_statement": "The team now wants to decide whether the AI/ML telemetry workflow is mature enough to become a controlled decision-support prototype. You receive the full evidence chain from L1 to L4: the 720-row original telemetry pack, the 690-row cleaned sample, selected telemetry fields, 26 anomaly flags, integration output schema, latency expectation of 500 milliseconds, a revised LLM report, a risk register with 11 open or mitigated risks, and a stakeholder request for a final readiness recommendation. However, no labelled failure dataset exists, some field metadata is still incomplete, two risks remain unresolved, and the report must not be used as an autonomous engineering decision. You must decide whether the AI/ML workflow is ready as a supervised decision-support prototype, ready only for further controlled testing, or blocked until stronger evidence and governance controls are added."}]}', '{"engage": {"color": "#6366f1", "label": "Engage", "estLabel": "20-30 minutes", "purposeTag": "Workplace Risk", "description": "Understand the workplace situation and why telemetry evidence-readiness matters before AI/ML anomaly-detection work."}, "evolve": {"color": "#ec4899", "label": "Evolve", "estLabel": "20-30 minutes", "purposeTag": "Reflect & Transfer", "description": "Reflect on feedback and transfer the readiness-validation logic to another dataset, sensor stream, or industry case."}, "empower": {"color": "#10b981", "label": "Empower", "estLabel": "20-30 minutes", "purposeTag": "Evidence-Based Decision", "description": "Make and defend a ready, partially ready, blocked, or escalation-needed decision using evidence."}, "explain": {"color": "#0ea5e9", "label": "Explain", "estLabel": "20-30 minutes", "purposeTag": "Learn Boundary / Concept", "description": "Learn the concept or role boundary needed to understand evidence quality without overclaiming root cause or model-readiness."}, "explore": {"color": "#8b5cf6", "label": "Explore", "estLabel": "20-30 minutes", "purposeTag": "Inspect Evidence", "description": "Inspect case evidence such as dataset summary, missing values, timestamps, packet sequence, logs, UDP description, and field list."}, "express": {"color": "#f59e0b", "label": "Express", "estLabel": "20-30 minutes", "purposeTag": "Create Artifact", "description": "Create the practice artifact using visible evidence, role-safe reasoning, and template fields."}}', '2026-06-09 05:32:56.199523+00', '2026-06-09 05:32:56.199523+00', 'ramya03@acharya.ac.in'), ('a2b3c4d5-e6f7-4a8b-9c0d-1e2f3a4b5c6d', 'finance-compensation', 'finance', 'Naresh Kumar', false, '[{"id": "dom-001", "code": "D001", "name": "Degree", "industry": "Finance", "is_active": true, "created_at": "2026-03-30T00:00:00Z", "updated_at": "2026-03-30T00:00:00Z"}, {"id": "dom-002", "code": "D002", "name": "Degree", "industry": "Finance", "is_active": true, "created_at": "2026-03-30T00:00:00Z", "updated_at": "2026-03-30T00:00:00Z"}]', '[{"id": "role-001", "name": "Compensation & Beneficiary", "domain_id": "dom-001", "is_active": true, "created_at": "2026-03-31T00:00:00Z", "updated_at": "2026-03-31T00:00:00Z", "description": "Builds and validates ML models on real-time machine telemetry data."}, {"id": "role-002", "name": "Compensation & Beneficiary", "domain_id": "dom-001", "is_active": true, "created_at": "2026-03-31T00:00:00Z", "updated_at": "2026-03-31T00:00:00Z", "description": "Builds both frontend and backend components of an application."}]', '{"id": "learner-001", "is_active": true, "created_at": "2024-01-01T00:00:00Z", "student_id": "3531e63e-589e-46e7-9248-4a769e84b00d", "updated_at": "2024-01-01T00:00:00Z", "grade_level": "Degree", "skill_level": "Beginner"}', '[{"id": "lc-001", "gap_score": 60, "created_at": "2024-01-01T00:00:00Z", "learner_id": "learner-001", "updated_at": "2024-01-01T00:00:00Z", "why_needed": "Monitor production systems and diagnose runtime issues", "how_to_build": "Complete observability course with logging, debugging, and monitoring tools", "target_level": 4, "assessment_id": "d9c8e5f2-1a2b-4c3d-9e8f-7a6b5c4d3e2f", "capability_id": "SE-CAP-08", "current_level": "beginner", "current_score": 20, "priority_band": "A"}, {"id": "lc-002", "gap_score": 40, "created_at": "2024-01-01T00:00:00Z", "learner_id": "learner-001", "updated_at": "2024-01-01T00:00